 lensOpen=true;lensC=c;lensTap={t:0,x:0,y:0};lensSaved={S:S,TX:TX,TY:TY};
 var cx=Math.min(W-10,Math.max(10,b.gx)),cy=Math.min(H-10,Math.max(10,b.gy));
