 if(!res){var sv=$('lsvg');sv.setAttribute('viewBox','0 0 200 120');sv.innerHTML='<ellipse cx="100" cy="60" rx="60" ry="36" fill="#ff5a1f" opacity=".35"/>'}
 var u=baseOf(c),nd=dm.svg.node();nd.style.transition='transform .45s cubic-bezier(.7,0,.2,1)';
 S=60;TX=W/2-u[0]*S;TY=H/2-u[1]*S;apply();
 setTimeout(function(){nd.style.transition=''},500);
 var L=$('lens');L.style.display='flex';
 var R=Math.hypot(Math.max(cx,W-cx),Math.max(cy,H-cy))+12;L.__c=[cx,cy,R];
 if(lensAnim)try{lensAnim.cancel()}catch(e){}
 if(L.animate)lensAnim=L.animate([{clipPath:'circle('+(s*0.35)+'px at '+cx+'px '+cy+'px)'},{clipPath:'circle('+R+'px at '+cx+'px '+cy+'px)'}],{duration:450,easing:'cubic-bezier(.7,0,.2,1)'});
